```{ojs}
//| echo: false
aa = 2600
bj = 2.0
ccost = 230
ffix = 450000

Ai = (aa + bi * ccost) / (2 * bi)
Bi = di / (2 * bi)
Aj = (aa + bj * ccost) / (2 * bj)
Bj = dj / (2 * bj)

den = 1 - Bi * Bj
stable = den > 0.02

eqPi = stable ? (Ai + Bi * Aj) / den : null
eqPj = stable ? (Aj + Bj * Ai) / den : null
eqQi = stable ? aa - bi * eqPi + di * eqPj : null
eqProfitI = stable ? (eqPi - ccost) * eqQi - ffix : null
eqQj = stable ? aa - bj * eqPj + dj * eqPi : null
eqProfitJ = stable ? (eqPj - ccost) * eqQj - ffix : null

money = d3.format("$,.0f")

html`<div style="font-size:15px;margin:.2rem 0 .5rem 0;color:#1F2937">${
  stable
    ? html`Equilibrium: you charge <b>${money(eqPi)}</b> and earn
           <b>${money(eqProfitI)}</b>; they charge <b>${money(eqPj)}</b> and earn
           <b>${money(eqProfitJ)}</b>.`
    : html`<span style="color:#C2410C;font-weight:600">No equilibrium.</span>
           The two best responses no longer cross — each firm's price chases the
           other's upward without settling.`
}</div>`
```

